use super::load_policy::PowerOfTwoLoadPolicy;

#[derive(Clone, Debug)]
pub struct HopscotchMap<K, V> {
    entries: Vec<(K, V)>,
    bucket_count: usize,
    load_policy: PowerOfTwoLoadPolicy,
}

impl<K: Eq, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K: Eq, V> HopscotchMap<K, V> {
    pub fn new() -> Self {
        Self {
            entries: Vec::new(),
            bucket_count: 0,
            load_policy: PowerOfTwoLoadPolicy::default(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> bool {
        if self
            .entries
            .iter()
            .any(|(existing_key, _)| existing_key == &entry.0)
        {
            return false;
        }

        let next_len = self.entries.len() + 1;
        if self.load_policy.max_entries_for(self.bucket_count) < next_len {
            self.bucket_count = self.load_policy.minimal_bucket_count(next_len);
        }

        self.entries.push(entry);
        true
    }

    pub fn load_factor(&self) -> f64 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.entries.len() as f64 / self.bucket_count as f64
        }
    }

    pub fn max_load_factor(&mut self, value: f64) {
        self.load_policy.set_max_load_factor(value);
    }

    pub fn rehash(&mut self, minimum_bucket_count: usize) {
        let requested = self.load_policy.normalize_bucket_count(minimum_bucket_count);
        let required = self.load_policy.minimal_bucket_count(self.entries.len());
        self.bucket_count = requested.max(required);
    }
}

