    max_load_factor: f64,
}

impl Default for PowerOfTwoLoadPolicy {
    fn default() -> Self {
        Self {
            max_load_factor: 0.9,
        }
    }
}

impl PowerOfTwoLoadPolicy {
    pub fn set_max_load_factor(&mut self, value: f64) {
        assert!(value.is_finite() && value > 0.0, "max load factor must be positive");
        self.max_load_factor = value;
    }

    pub fn max_entries_for(&self, bucket_count: usize) -> usize {
        if bucket_count == 0 {
            0
        } else {
            ((bucket_count as f64) * self.max_load_factor).floor() as usize
        }
    }

    pub fn minimal_bucket_count(&self, len: usize) -> usize {
        if len == 0 {
            return 0;
        }

        let mut bucket_count = 2usize;
        while self.max_entries_for(bucket_count) < len {
            bucket_count = bucket_count.checked_mul(2).expect("bucket count overflow");
        }
        bucket_count
    }

    pub fn normalize_bucket_count(&self, requested: usize) -> usize {
        match requested {
            0 => 0,
            1 => 2,
            _ => requested.next_power_of_two(),
        }
    }
}

