pub fn format_cpp_float(value: f64) -> String {
    let mut text = format!("{value:.6}");

    if let Some(dot_index) = text.find('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.len() == dot_index + 1 {
            text.pop();
        }
    }

    if text == "-0" {
        text.clear();
        text.push('0');
    }

    text
}

